    51→class Chalk::EarleyChart {
    52→    field $semiring :param;
    53→    field %chart;
    54→    field @by_end_pos;
    55→    field %predicted;    # Track what we've predicted at each position
    56→    field %completed;    # Track what we've completed
    57→
    58→    method add_item($earley_item) {
    59→        $chart{ $earley_item->key } = $earley_item;
    60→    }
    61→
    62→    method get_element($key) { $chart{$key} }
