    65→        my $key     = $item->key;
    66→        my $current = $self->get_element($key);
    67→        $chart{$key} = $current ? $current + $element : $element;
    68→
    69→        push( $by_end_pos[ $item->end_pos ]->@*, $item );
    70→
    71→        return $chart{$key};
    72→    }
