    87→    method mark_predicted( $nonterminal, $pos, $rule_id ) {
    88→        $predicted{"$nonterminal|$pos|$rule_id"} = 1;
    89→    }
    90→
    91→    method has_completed($item) {
    92→        return exists( $completed{$item} );
    93→    }
    94→
    95→    method mark_completed($item) {
    96→        $completed{$item} = 1;
    97→    }
    98→
    99→    method goal_value( $start_symbol, $n ) {
   100→
   101→        # Find all complete items that span [0,n] with LHS = start_symbol
   102→        my $result = $semiring->add_id;
   103→
   104→        my @items = $self->items_ending_at($n);
   105→
   106→        for my $item (@items) {
   107→            next unless $item->complete;
   108→            next unless $item->start_pos == 0;
   109→            next unless $item->rule->lhs eq $start_symbol;
   110→
   111→            my $element = $self->get_element($item);
   112→            if ($element) {
   113→                $result = $result + $element;
   114→            }
   115→        }
   116→
   117→        # Check if we found any valid parses
   118→        return $result == $semiring->add_id ? undef : $result;
   119→    }
   120→}
