   122→class Chalk::Parser {
   123→    field $semiring :param = Chalk::Semiring::SPPFViterbiSemiring->new();
   124→    field $grammar :param;
   125→    field $preprocess :param = [];  # Arrayref of preprocessor class names
   126→
   127→    method parse_string($input_string) {
   128→        # Apply preprocessors in sequence
   129→        for my $preprocessor_class (@$preprocess) {
   130→            next unless defined $preprocessor_class;
   131→
   132→            # Load the preprocessor module
   133→            (my $file = $preprocessor_class) =~ s{::}{/}g;
   134→            require "$file.pm";
   135→
   136→            # Apply preprocessing
   137→            my $preprocessor = $preprocessor_class->new(input => $input_string);
   138→            $preprocessor->transform();
   139→            $input_string = $preprocessor->output;
   140→        }
   141→
   142→        my $chart = Chalk::EarleyChart->new( semiring => $semiring );
   143→
   144→       # Initialize chart by predicting all rules for start symbol at position 0
   145→        my $start_symbol = $grammar->start_symbol;
   146→        for my $rule ( $grammar->rules_for($start_symbol) ) {
   147→            my $start_item = Chalk::EarleyItem->new(
   148→                start_pos => 0,
   149→                rule      => $rule,
   150→                dot_pos   => 0,
   151→                end_pos   => 0,
   152→            );
   153→
   154→            my $start_element = $semiring->init_element_from_rule($rule, 0, 0);
   155→            $chart->add_element( $start_item, $start_element );
   156→        }
   157→
   158→        # Process positions from 0 to end of string
   159→        my $pos             = 0;
   160→        my $input_length    = length($input_string);
   161→        my $last_active_pos = 0;
   162→
   163→        while ( $pos <= $input_length ) {
   164→            my @agenda_before = $chart->items_ending_at($pos);
   165→            $self->process_position_string( $pos, $chart, $input_string );
   166→
   167→            # Track the last position where we had active items
   168→            if ( @agenda_before > 0 ) {
   169→                $last_active_pos = $pos;
   170→            }
   171→
   172→            ++$pos;
   173→        }
   174→
   175→        my $result =
   176→          $chart->goal_value( $grammar->start_symbol, $input_length );
   177→
   178→        # Show where parsing actually stopped if it failed
   179→        if ( !$result && $last_active_pos < $input_length ) {
   180→            warn(
   181→"🔍 PARSING STOPPED: Reached position $last_active_pos of $input_length ("
   182→                  . sprintf( "%.1f", 100 * $last_active_pos / $input_length )
   183→                  . "%)\n" );
   184→        }
   185→
   186→        return $result;
   187→    }
   188→
   189→    method process_position_string( $pos, $chart, $input_string ) {
   190→        my @agenda = $chart->items_ending_at($pos);
   191→
   192→        while ( my $item = shift(@agenda) ) {
   193→            my $element = $chart->get_element($item);
   194→            next unless defined($element);
   195→
   196→            if ( $item->complete ) {
   197→                $self->complete( $item, $element, $chart, \@agenda );
   198→            }
   199→            elsif ( defined( my $next_sym = $item->next_symbol ) ) {
   200→                if ( $grammar->is_nonterminal($next_sym) ) {
   201→                    $self->predict( $item, $next_sym, $chart, \@agenda );
   202→                }
   203→                else {
   204→                    # Try to match terminal with lexeme support
   205→                    my $pattern = $item->rule->terminal_to_regex($next_sym);
   206→                    pos($input_string) = $pos;
   207→                    if ( $input_string =~ /\G($pattern)/gc ) {
   208→                        my $match_length = length($1);
   209→                        $self->scan( $item, $element, $chart, $pos,
   210→                            $match_length );
   211→                    }
   212→                }
   213→            }
   214→        }
   215→    }
   216→
   217→    method complete( $completed_item, $completed_element, $chart, $agenda ) {
   218→
   219→        # Check if we've already completed this item
   220→        return if $chart->has_completed($completed_item);
   221→        $chart->mark_completed($completed_item);
   222→
   223→        my $lhs = $completed_item->rule->lhs;
   224→
   225→        my @waiting = $chart->items_ending_at( $completed_item->start_pos );
   226→
   227→        # Separate Leo items from regular items
   228→        my @leo_waiting =
   229→          grep { $_ isa Chalk::LeoItem && $_->symbol eq $lhs } @waiting;
   230→        my @regular_waiting =
   231→          grep { !( $_ isa Chalk::LeoItem ) && !$_->complete } @waiting;
   232→
   233→        my @waiting_for_lhs = grep { $_->next_symbol eq $lhs } @regular_waiting;
   234→
   235→  # Check for deterministic reduction (only if no Leo items waiting)
   236→  # Leo items are only for deterministic right-recursive chains where:
   237→  # 1. Only one item is waiting for this LHS
   238→  # 2. The waiting item will be complete after this reduction
   239→  # 3. The rule is right-recursive
   240→  #
   241→  # NOTE: Joop Leo's second optimization for left-recursion could be implemented
   242→  # here, but performance testing shows left-recursion is already faster than
   243→  # right-recursion in our Earley implementation, so it's not needed.
   244→        if (   @waiting_for_lhs == 1
   245→            && @leo_waiting == 0
   246→            && $waiting_for_lhs[0]->rule->is_right_recursive
   247→            && $waiting_for_lhs[0]->dot_pos ==
   248→            scalar( $waiting_for_lhs[0]->rule->rhs->@* ) - 1 )
   249→        {
   250→            my $waiting_item = $waiting_for_lhs[0];
   251→
   252→            # Use completed item's end position
   253→            my $leo = Chalk::LeoItem->new(
   254→                symbol    => $lhs,
   255→                start_pos => $waiting_item->start_pos,
   256→                end_pos   => $completed_item->end_pos,
   257→                top_item  => $waiting_item,
   258→            );
   259→
   260→            my $waiting_element = $chart->get_element($waiting_item);
   261→            next unless $waiting_element;
   262→            my $combined_element = $waiting_element * $completed_element;
   263→            $chart->add_element( $leo, $combined_element );
   264→            push( @$agenda, $leo );
   265→            return;    # Skip normal completion
   266→        }
   267→
   268→        # Normal completion for regular items
   269→        for my $waiting_item (@waiting_for_lhs) {
   270→
   271→            my $waiting_element = $chart->get_element($waiting_item);
   272→            next unless $waiting_element;
   273→
   274→            # Semiring multiplication ⊗ combines sequential components
   275→            my $combined_element = $waiting_element * $completed_element;
   276→
   277→            my $new_item = Chalk::EarleyItem->new(
   278→                start_pos => $waiting_item->start_pos,
   279→                rule      => $waiting_item->rule,
   280→                dot_pos   => $waiting_item->dot_pos + 1,
   281→                end_pos   => $completed_item->end_pos
   282→            );
   283→
   284→            # Only add if not already in chart
   285→            unless ( $chart->has_item($new_item) ) {
   286→                $chart->add_element( $new_item, $combined_element );
   287→                push( @$agenda, $new_item );
   288→            }
   289→        }
   290→
   291→        # Handle Leo items waiting for this completion
   292→        for my $leo_item (@leo_waiting) {
   293→
   294→            # Unpack the Leo chain to get the original waiting item
   295→            my $current = $leo_item->top_item;
   296→            while ( $current isa Chalk::LeoItem ) {
   297→                $current = $current->top_item;
   298→            }
   299→
   300→            # Now $current is the original EarleyItem at the bottom of the chain
   301→            # Complete it with the current completed item
   302→            my $waiting_element = $chart->get_element($leo_item);
   303→            next unless $waiting_element;
   304→            my $combined_element = $waiting_element * $completed_element;
   305→
   306→            my $new_item = Chalk::EarleyItem->new(
   307→                start_pos => $current->start_pos,
   308→                rule      => $current->rule,
   309→                dot_pos   => $current->dot_pos + 1,
   310→                end_pos   => $completed_item->end_pos
   311→            );
   312→
   313→            # Only add if not already in chart
   314→            unless ( $chart->has_item($new_item) ) {
   315→                $chart->add_element( $new_item, $combined_element );
   316→                push( @$agenda, $new_item );
   317→            }
   318→        }
   319→    }
   320→
   321→    method predict( $item, $nonterminal, $chart, $agenda ) {
   322→        my $pos = $item->end_pos;
   323→
   324→# Check if we've already predicted this nonterminal from this rule at this position
   325→# Multiple rules can predict the same nonterminal, so we track by rule origin
   326→        return if $chart->has_predicted( $nonterminal, $pos, $item->rule->id );
   327→        $chart->mark_predicted( $nonterminal, $pos, $item->rule->id );
   328→
   329→        for my $rule ( $grammar->rules_for($nonterminal) ) {
   330→            my $predicted_item = Chalk::EarleyItem->new(
   331→                start_pos => $pos,
   332→                rule      => $rule,
   333→                dot_pos   => 0,
   334→                end_pos   => $pos
   335→            );
   336→
   337→            # Only add if not already in chart
   338→            unless ( $chart->has_item($predicted_item) ) {
   339→                my $rule_element = $semiring->init_element_from_rule($rule, $pos, $pos);
   340→                $chart->add_element( $predicted_item, $rule_element );
   341→                push( @$agenda, $predicted_item );
   342→            }
   343→        }
   344→
   345→        # Aycock-Horspool optimization: if the nonterminal is nullable,
   346→        # we can also advance the dot past it immediately
   347→        if ( $grammar->is_nullable($nonterminal) ) {
   348→            my $advanced_item = Chalk::EarleyItem->new(
   349→                start_pos => $item->start_pos,
   350→                rule      => $item->rule,
   351→                dot_pos   => $item->dot_pos + 1,
   352→                end_pos   => $item->end_pos
   353→            );
   354→
   355→            # Only add if not already present
   356→            unless ( $chart->has_item($advanced_item) ) {
   357→                my $current_element = $chart->get_element($item);
   358→                if ($current_element) {
   359→                    $chart->add_element( $advanced_item, $current_element );
   360→                    push( @$agenda, $advanced_item );
   361→                }
   362→            }
   363→        }
   364→    }
   365→
   366→    method scan( $item, $element, $chart, $pos, $match_length ) {
   367→        my $scanned_item = Chalk::EarleyItem->new(
   368→            start_pos => $item->start_pos,
   369→            rule      => $item->rule,
   370→            dot_pos   => $item->dot_pos + 1,
   371→            end_pos   => $pos + $match_length
   372→        );
   373→
   374→        # All semirings receive position updates during scan
   375→        # Semirings can choose to use or ignore positions based on their needs
   376→        my $scanned_element = $semiring->init_element_from_rule(
   377→            $item->rule,
   378→            $scanned_item->start_pos,
   379→            $scanned_item->end_pos
   380→        );
   381→
   382→        $chart->add_element( $scanned_item, $scanned_element );
   383→    }
   384→}
   385→
   386→1;
