     1→# ABOUTME: Grammar and rule definitions for Chalk parser
     2→# ABOUTME: Provides GrammarRule and Grammar classes for defining parsing grammars
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::GrammarRule {
     8→
     9→    # Supports both exact token matching and lexeme/regex patterns for terminals
    10→    # Use parse() for pre-tokenized input, parse_string() for lexeme matching
    11→    #
    12→    # TODO: Consider matrix-based Earley parsing optimization
    13→    # See: https://medium.com/@celine.y.lee/fast-earley-parsing-2216fb0909a3
    14→    # Matrix operations could optimize prediction/completion phases while
    15→    # lexemes handle terminal matching independently
    16→    use overload '""' => 'to_string';
    17→
    18→    state $next_id = 0;    # auto-incrementing rule ID
    19→    field $id  :reader = $next_id++;
    20→    field $lhs :param :reader;
    21→    field $rhs :param :reader;
    22→    field $probability :param :reader = 1.0;
    23→    field $nullable;
    24→
    25→    method is_right_recursive() { $lhs eq $rhs->[-1] }
    26→    method is_left_recursive()  { $lhs eq $rhs->[0] }
    27→
    28→    method is_nullable( $grammar, $seen = {} ) {
    29→        return $nullable if defined($nullable);    # memoize nullable
    30→
    31→        # Empty production is nullable
    32→        return $nullable = 1 if @$rhs == 0;
    33→
    34→        # All symbols in RHS must be nullable
    35→        return $nullable = 1 if all {
    36→            my @rules = $grammar->rules_for($_);
    37→
    38→            # Terminals (no rules) are not nullable
    39→            return 0 unless @rules;
    40→
    41→            # In cycle, assume not nullable
    42→            return 0 if $seen->{$_};
    43→
    44→            # Check if this symbol is nullable via any of its rules
    45→            $seen->{$_} = 1;
    46→            return 0 unless any { $_->is_nullable( $grammar, $seen ) } @rules;
    47→        } @$rhs;
    48→
    49→        return $nullable = 0;
    50→    }
    51→
    52→    method to_string(@) {
    53→        return "($id) $lhs -> " . join( ' ', $rhs->@* );
    54→    }
    55→
    56→    method terminal_to_regex($terminal) {
    57→        state %seen;
    58→
    59→        # Convert terminal to regex pattern
    60→        # If already a regex, return as-is
    61→        # If string literal, escape and convert to regex
    62→        return $seen{$terminal} //=
    63→          ref($terminal) eq 'Regexp' ? $terminal : qr/\Q$terminal\E/;
    64→    }
    65→}
    66→
    67→class Chalk::Grammar {
    68→    field $rules        :param :reader;
    69→    field $start_symbol :param :reader;
    70→    field %nullable_cache;
    71→
    72→    ADJUST {
    73→        for my $s ( keys(%$rules) ) {
    74→            $self->is_nullable($s);
    75→        }
    76→    }
    77→
    78→    my sub new_rule( $lhs, $rhs, $probability = 1.0 ) {
    79→        $probability ||= 0.1;
    80→        return Chalk::GrammarRule->new(
    81→            lhs         => $lhs,
    82→            rhs         => $rhs,
    83→            probability => $probability
    84→        );
    85→    }
    86→
    87→    my sub insert ( $items, @list ) {
    88→        return [ ( map { $_, @$items } @list[ 0 .. $#list - 1 ] ), $list[-1] ];
    89→    }
    90→
    91→    sub build_grammar( $class, $auto_insert, @rules ) {
    92→        my %rules = ();
    93→        for my $r (@rules) {
    94→            my ( $lhs, $rhs ) = @$r;
    95→            if ( @$auto_insert && @$rhs > 1 ) {
    96→                $r->[1] = insert( $auto_insert, @$rhs );
    97→            }
    98→            push( @{ $rules{$lhs} //= [] }, new_rule(@$r) );
    99→        }
   100→        return Chalk::Grammar->new( rules => \%rules, start_symbol => $rules[0]->[0] );
   101→    }
   102→
   103→    method start_rule() { return $rules->{$start_symbol}->[0] }
   104→
   105→    method rules_for($symbol) {
   106→        return $rules->{$symbol}->@* if exists( $rules->{$symbol} );
   107→        return;
   108→    }
   109→
   110→    method is_nonterminal($symbol) {
   111→        return exists( $rules->{$symbol} );
   112→    }
   113→
   114→    method is_nullable($symbol) {
   115→
   116→        # Check cache first
   117→        return $nullable_cache{$symbol} if exists( $nullable_cache{$symbol} );
   118→
   119→       # Compute nullability by checking if any rule for this symbol is nullable
   120→        my $result = 0;
   121→        for my $rule ( $self->rules_for($symbol) ) {
   122→            if ( $rule->is_nullable($self) ) {
   123→                $result = 1;
   124→                last;
   125→            }
   126→        }
   127→
   128→        # Cache the result
   129→        $nullable_cache{$symbol} = $result;
   130→        return $result;
   131→    }
   132→
   133→    method to_string(@) {
   134→        my $grammar = '';
   135→        $grammar .= "Grammar:\n";
   136→        for my $nt ( sort( keys( $rules->%* ) ) ) {
   137→            for my $rule ( $rules->{$nt}->@* ) {
   138→                $grammar .= "  $rule\n";
   139→            }
   140→        }
   141→        $grammar .= "\n";
   142→        return $grammar;
   143→    }
   144→}
   145→
   146→1;
   147→

