-        if ($rhs[$i] eq $rule->lhs) {
-            # Check if everything after position $i is nullable
-            my $all_nullable = 1;
-            for my $j ($i + 1 .. $#rhs) {
-                unless ($self->is_nullable($rhs[$j])) {
-                    $all_nullable = 0;
-                    last;
-                }
-            }
-            return 1 if $all_nullable;
-        }
-    }
-    return 0;
-}
-```
