-        # Check if any rule for this symbol has all nullable RHS
-        for my $rule (@grammar_rules) {
-            if ($rule->lhs eq $symbol) {
-                if ($rule->rhs_length == 0) {  # Empty RHS
-                    return $nullable_cache{$symbol} = 1;
-                }
-                
-                my $all_nullable = 1;
-                for my $rhs_symbol ($rule->rhs->@*) {
