   341→
   342→            my $start_element = $semiring->init_element_from_rule($rule);
   343→            $chart->add_element( $start_item, $start_element );
   344→        }
   345→
   346→        # Process positions from 0 to end of string
   347→        my $pos             = 0;
   348→        my $input_length    = length($input_string);
   349→        my $last_active_pos = 0;
   350→
   351→        while ( $pos <= $input_length ) {
   352→            my @agenda_before = $chart->items_ending_at($pos);
   353→            
   354→            
   355→            $self->process_position_string( $pos, $chart, $input_string );
   356→
   357→            # Track the last position where we had active items
   358→            if ( @agenda_before > 0 ) {
   359→                $last_active_pos = $pos;
   360→            }
   361→
   362→            ++$pos;
   363→        }
   364→
   365→        my $result =
   366→          $chart->goal_value( $grammar->start_symbol, $input_length );
   367→
   368→        # Show where parsing actually stopped if it failed
   369→        if ( !$result && $last_active_pos < $input_length ) {
   370→            warn(
   371→"🔍 PARSING STOPPED: Reached position $last_active_pos of $input_length ("
   372→                  . sprintf( "%.1f", 100 * $last_active_pos / $input_length )
   373→                  . "%)\n" );
   374→        }
   375→
   376→        return $result;
   377→    }
   378→
   379→    method process_position_string( $pos, $chart, $input_string ) {
   380→        my @agenda = $chart->items_ending_at($pos);
   381→
   382→        while ( my $item = shift(@agenda) ) {
   383→            my $element = $chart->get_element($item);
   384→            next unless defined($element);
   385→
   386→            if ( $item->complete ) {
   387→                $self->complete( $item, $element, $chart, \@agenda );
   388→            }
   389→            elsif ( defined( my $next_sym = $item->next_symbol ) ) {
   390→                if ( $grammar->is_nonterminal($next_sym) ) {
   391→                    $self->predict( $item, $next_sym, $chart, \@agenda );
   392→                }
   393→                else {
   394→                    # Try to match terminal with lexeme support
   395→                    my $pattern = $item->rule->terminal_to_regex($next_sym);
   396→                    pos($input_string) = $pos;
   397→                    if ( $input_string =~ /\G($pattern)/gc ) {
   398→                        my $match_length = length($1);
   399→                        $self->scan( $item, $element, $chart, $pos,
   400→                            $match_length );
   401→                    }
   402→                }
   403→            }
   404→        }
   405→    }
   406→
   407→    method complete( $completed_item, $completed_element, $chart, $agenda ) {
   408→
   409→        # Check if we've already completed this item
   410→        return if $chart->has_completed($completed_item);
   411→        $chart->mark_completed($completed_item);
   412→
   413→        my $lhs = $completed_item->rule->lhs;
   414→
   415→        my @waiting = $chart->items_ending_at( $completed_item->start_pos );
   416→
   417→        # Separate Leo items from regular items
   418→        my @leo_waiting =
   419→          grep { $_ isa LeoItem && $_->symbol eq $lhs } @waiting;
   420→        my @regular_waiting =
   421→          grep { !( $_ isa LeoItem ) && !$_->complete } @waiting;
   422→
   423→        my @waiting_for_lhs = grep { $_->next_symbol eq $lhs } @regular_waiting;
   424→
   425→  # Check for deterministic reduction (only if no Leo items waiting)
   426→  # Leo items are only for deterministic right-recursive chains where:
   427→  # 1. Only one item is waiting for this LHS
   428→  # 2. The waiting item will be complete after this reduction
   429→  # 3. The rule is right-recursive
   430→  #
   431→  # NOTE: Joop Leo's second optimization for left-recursion could be implemented
   432→  # here, but performance testing shows left-recursion is already faster than
   433→  # right-recursion in our Earley implementation, so it's not needed.
   434→        if (   @waiting_for_lhs == 1
   435→            && @leo_waiting == 0
   436→            && $waiting_for_lhs[0]->rule->is_right_recursive
   437→            && $waiting_for_lhs[0]->dot_pos ==
   438→            scalar( $waiting_for_lhs[0]->rule->rhs->@* ) - 1 )
   439→        {
   440→            my $waiting_item = $waiting_for_lhs[0];
   441→
   442→            # Use completed item's end position
   443→            my $leo = LeoItem->new(
   444→                symbol    => $lhs,
   445→                start_pos => $waiting_item->start_pos,
   446→                end_pos   => $completed_item->end_pos,
   447→                top_item  => $waiting_item,
   448→            );
   449→
   450→            my $waiting_element = $chart->get_element($waiting_item);
   451→            next unless $waiting_element;
   452→            my $combined_element = $waiting_element * $completed_element;
   453→            $chart->add_element( $leo, $combined_element );
   454→            push( @$agenda, $leo );
   455→            return;    # Skip normal completion
   456→        }
   457→
   458→        # Normal completion for regular items
   459→        for my $waiting_item (@waiting_for_lhs) {
   460→
   461→            my $waiting_element = $chart->get_element($waiting_item);
   462→            next unless $waiting_element;
   463→
   464→            # Semiring multiplication ⊗ combines sequential components
   465→            my $combined_element = $waiting_element * $completed_element;
   466→
   467→            my $new_item = EarleyItem->new(
   468→                start_pos => $waiting_item->start_pos,
   469→                rule      => $waiting_item->rule,
   470→                dot_pos   => $waiting_item->dot_pos + 1,
   471→                end_pos   => $completed_item->end_pos
   472→            );
   473→
   474→            # Only add if not already in chart
   475→            unless ( $chart->has_item($new_item) ) {
   476→                $chart->add_element( $new_item, $combined_element );
   477→                push( @$agenda, $new_item );
   478→            }
   479→        }
   480→
   481→        # Handle Leo items waiting for this completion
   482→        for my $leo_item (@leo_waiting) {
   483→
   484→            # Unpack the Leo chain to get the original waiting item
   485→            my $current = $leo_item->top_item;
   486→            while ( $current isa LeoItem ) {
   487→                $current = $current->top_item;
   488→            }
   489→
   490→            # Now $current is the original EarleyItem at the bottom of the chain
   491→            # Complete it with the current completed item
   492→            my $waiting_element = $chart->get_element($leo_item);
   493→            next unless $waiting_element;
   494→            my $combined_element = $waiting_element * $completed_element;
   495→
   496→            my $new_item = EarleyItem->new(
   497→                start_pos => $current->start_pos,
   498→                rule      => $current->rule,
   499→                dot_pos   => $current->dot_pos + 1,
   500→                end_pos   => $completed_item->end_pos
   501→            );
   502→
   503→            # Only add if not already in chart
   504→            unless ( $chart->has_item($new_item) ) {
   505→                $chart->add_element( $new_item, $combined_element );
   506→                push( @$agenda, $new_item );
   507→            }
   508→        }
   509→    }
   510→
   511→    method predict( $item, $nonterminal, $chart, $agenda ) {
   512→        my $pos = $item->end_pos;
   513→
   514→# Check if we've already predicted this nonterminal from this rule at this position
   515→# Multiple rules can predict the same nonterminal, so we track by rule origin
   516→        return if $chart->has_predicted( $nonterminal, $pos, $item->rule->id );
   517→        $chart->mark_predicted( $nonterminal, $pos, $item->rule->id );
   518→
   519→        for my $rule ( $grammar->rules_for($nonterminal) ) {
   520→            my $predicted_item = EarleyItem->new(
   521→                start_pos => $pos,
   522→                rule      => $rule,
   523→                dot_pos   => 0,
   524→                end_pos   => $pos
   525→            );
   526→
   527→            # Only add if not already in chart
   528→            unless ( $chart->has_item($predicted_item) ) {
   529→                my $rule_element = $semiring->init_element_from_rule($rule);
   530→                $chart->add_element( $predicted_item, $rule_element );
   531→                push( @$agenda, $predicted_item );
   532→            }
   533→        }
   534→
   535→        # Aycock-Horspool optimization: if the nonterminal is nullable,
   536→        # we can also advance the dot past it immediately
   537→        if ( $grammar->is_nullable($nonterminal) ) {
   538→            my $advanced_item = EarleyItem->new(
   539→                start_pos => $item->start_pos,
   540→                rule      => $item->rule,
   541→                dot_pos   => $item->dot_pos + 1,
   542→                end_pos   => $item->end_pos
   543→            );
   544→
   545→            # Only add if not already present
   546→            unless ( $chart->has_item($advanced_item) ) {
   547→                my $current_element = $chart->get_element($item);
   548→                if ($current_element) {
   549→                    $chart->add_element( $advanced_item, $current_element );
   550→                    push( @$agenda, $advanced_item );
   551→                }
   552→            }
   553→        }
   554→    }
   555→
   556→    method scan( $item, $element, $chart, $pos, $match_length ) {
   557→        my $scanned_item = EarleyItem->new(
   558→            start_pos => $item->start_pos,
   559→            rule      => $item->rule,
   560→            dot_pos   => $item->dot_pos + 1,
   561→            end_pos   => $pos + $match_length
   562→        );
   563→
   564→        $chart->add_element( $scanned_item, $element );
   565→    }
   566→
   567→}
   568→
   569→class GrammarRule {
   570→
   571→    # Supports both exact token matching and lexeme/regex patterns for terminals
   572→    # Use parse() for pre-tokenized input, parse_string() for lexeme matching
   573→    #
   574→    # TODO: Consider matrix-based Earley parsing optimization
   575→    # See: https://medium.com/@celine.y.lee/fast-earley-parsing-2216fb0909a3
   576→    # Matrix operations could optimize prediction/completion phases while
   577→    # lexemes handle terminal matching independently
   578→    use overload '""' => 'to_string';
   579→
   580→    state $next_id = 0;    # auto-incrementing rule ID
   581→    field $id  :reader = $next_id++;
   582→    field $lhs :param :reader;
   583→    field $rhs :param :reader;
   584→    field $probability :param :reader = 1.0;
   585→    field $nullable;
   586→
   587→    method is_right_recursive() { $lhs eq $rhs->[-1] }
   588→    method is_left_recursive()  { $lhs eq $rhs->[0] }
   589→
   590→    method is_nullable( $grammar, $seen = {} ) {
   591→        return $nullable if defined($nullable);    # memoize nullable
   592→
   593→        # Empty production is nullable
   594→        return $nullable = 1 if @$rhs == 0;
   595→
   596→        # All symbols in RHS must be nullable
   597→        return $nullable = 1 if all {
   598→            my @rules = $grammar->rules_for($_);
   599→
   600→            # Terminals (no rules) are not nullable
   601→            return 0 unless @rules;
   602→
   603→            # In cycle, assume not nullable
   604→            return 0 if $seen->{$_};
   605→
   606→            # Check if this symbol is nullable via any of its rules
   607→            $seen->{$_} = 1;
   608→            return 0 unless any { $_->is_nullable( $grammar, $seen ) } @rules;
   609→        } @$rhs;
   610→
   611→        return $nullable = 0;
   612→    }
   613→
   614→    method to_string(@) {
   615→        return "($id) $lhs -> " . join( ' ', $rhs->@* );
   616→    }
   617→
   618→    method terminal_to_regex($terminal) {
   619→        state %seen;
   620→
   621→        # Convert terminal to regex pattern
   622→        # If already a regex, return as-is
   623→        # If string literal, escape and convert to regex
   624→        return $seen{$terminal} //=
   625→          ref($terminal) eq 'Regexp' ? $terminal : qr/\Q$terminal\E/;
   626→    }
   627→}
   628→
   629→class Grammar {
   630→    field $rules        :param :reader;
   631→    field $start_symbol :param :reader;
   632→    field %nullable_cache;
   633→
   634→    ADJUST {
   635→        for my $s ( keys(%$rules) ) {
   636→            $self->is_nullable($s);
   637→        }
   638→    }
   639→
   640→    my sub new_rule( $lhs, $rhs, $probability = 1.0 ) {
   641→        $probability ||= 0.1;
   642→        return GrammarRule->new(
   643→            lhs         => $lhs,
   644→            rhs         => $rhs,
   645→            probability => $probability
   646→        );
   647→    }
   648→
   649→    my sub insert ( $items, @list ) {
   650→        return [ ( map { $_, @$items } @list[ 0 .. $#list - 1 ] ), $list[-1] ];
   651→    }
   652→
   653→    sub build_grammar( $class, $auto_insert, @rules ) {
   654→        my %rules = ();
   655→        for my $r (@rules) {
   656→            my ( $lhs, $rhs ) = @$r;
   657→            if ( @$auto_insert && @$rhs > 1 ) {
   658→                $r->[1] = insert( $auto_insert, @$rhs );
   659→            }
   660→            push( @{ $rules{$lhs} //= [] }, new_rule(@$r) );
   661→        }
   662→        return Grammar->new( rules => \%rules, start_symbol => $rules[0]->[0] );
   663→    }
   664→
   665→    method start_rule() { return $rules->{$start_symbol}->[0] }
   666→
   667→    method rules_for($symbol) {
   668→        return $rules->{$symbol}->@* if exists( $rules->{$symbol} );
   669→        return;
   670→    }
   671→
   672→    method is_nonterminal($symbol) {
   673→        return exists( $rules->{$symbol} );
   674→    }
   675→
   676→    method is_nullable($symbol) {
   677→
   678→        # Check cache first
   679→        return $nullable_cache{$symbol} if exists( $nullable_cache{$symbol} );
   680→
   681→       # Compute nullability by checking if any rule for this symbol is nullable
   682→        my $result = 0;
   683→        for my $rule ( $self->rules_for($symbol) ) {
   684→            if ( $rule->is_nullable($self) ) {
   685→                $result = 1;
   686→                last;
   687→            }
   688→        }
   689→
   690→        # Cache the result
   691→        $nullable_cache{$symbol} = $result;
   692→        return $result;
   693→    }
   694→
   695→    method to_string(@) {
   696→        my $grammar = '';
   697→        $grammar .= "Grammar:\n";
   698→        for my $nt ( sort( keys( $rules->%* ) ) ) {
   699→            for my $rule ( $rules->{$nt}->@* ) {
   700→                $grammar .= "  $rule\n";
   701→            }
   702→        }
   703→        $grammar .= "\n";
   704→        return $grammar;
   705→    }
   706→}
   707→
   708→# Main execution when run as script
   709→if ( !caller ) {
   710→    require "./chalk-grammar.pl";
   711→    our $chalk_grammar;
   712→
   713→    # Debug: check if grammar loaded
   714→    if ( !defined($chalk_grammar) ) {
   715→        die("Error: Grammar not loaded!\n");
   716→    }
   717→
   718→    # Read input from STDIN or command line file
   719→    my $input;
   720→    if (@ARGV) {
   721→
   722→        # Read from file
   723→        my $filename = $ARGV[0];
   724→        open( my $fh, '<', $filename ) or die("Cannot open $filename: $!\n");
   725→        local $/;    # slurp mode
   726→        $input = <$fh>;
   727→        close($fh);
   728→    }
   729→    else {
   730→        # Read from STDIN
   731→        local $/;    # slurp mode
   732→        $input = <STDIN>;
   733→    }
   734→
   735→    chomp($input) if defined($input);
   736→
   737→    if ( defined($input) && length($input) > 0 ) {
   738→
   739→        # Create parser with grammar
   740→        my $parser = Parser->new( grammar => $chalk_grammar );
   741→
   742→        # Parse the input
   743→        my $result = $parser->parse_string($input);
   744→
   745→        # Print the result
   746→        if ($result) {
   747→            print("Parse successful: $result\n");
   748→        }
   749→        else {
   750→            print("Parse failed\n");
   751→        }
   752→    }
   753→    else {
   754→        print("No input provided\n");
   755→    }
   756→}
