#!/usr/bin/env perl
# ABOUTME: Script to refactor build_grammar calls to use named parameters
# ABOUTME: Converts old positional format to new auto_insert/rules format

use 5.42.0;
use strict;
use warnings;

my $file = $ARGV[0] or die "Usage: $0 <file>\n";

# Read the entire file
open my $fh, '<', $file or die "Cannot open $file: $!\n";
my @lines = <$fh>;
close $fh;

# Process the lines
my $modified = 0;
for (my $i = 0; $i < @lines; $i++) {
    my $line = $lines[$i];

    # Pattern 1: Single-line call with single rule array (no auto_insert)
    # Grammar->build_grammar( [ 'A' => [] ] )
    if ($line =~ /^(\s*)(my \$grammar|\$grammar) = .*->build_grammar\(\s*\[\s*'/ && $line =~ /\]\s*\)\s*;\s*$/) {
        $line =~ s/^(\s*)(my \$grammar|\$grammar) = (.*->build_grammar)\(\s*/$1$2 = $3(\n$1    rules => [\n$1        /;
        $line =~ s/\s*\)\s*;\s*$/\n$1    ]\n$1);\n/;
        $lines[$i] = $line;
        $modified = 1;
        next;
    }

    # Pattern 2: Multi-line call starting with auto_insert array
    # Grammar->build_grammar(
    #     [],  or  ['WS_OPT'],
    if ($line =~ /^(\s*)(?:my \$grammar|\$grammar) = .*->build_grammar\(\s*$/) {
        my $indent = $1;
        my $var_line = $line;

        # Look at next line for auto_insert array
        if ($i + 1 < @lines && $lines[$i + 1] =~ /^\s*\[(.*?)\],\s*$/) {
            my $auto_insert = $1;
            # Skip the auto_insert line and add our formatted version
            $lines[$i + 1] = "${indent}    auto_insert => [$auto_insert],\n${indent}    rules => [\n";
            $modified = 1;

            # Find the closing paren and add closing bracket for rules
            for (my $j = $i + 2; $j < @lines; $j++) {
                if ($lines[$j] =~ /^(\s*)\)\s*;\s*$/) {
                    $lines[$j] = "$1    ]\n$1);\n";
                    last;
                }
            }
        }
        next;
    }

    # Pattern 3: Multi-line call starting without auto_insert (just rules)
    # Grammar->build_grammar(
    #     [ 'Rule' => [...] ],
    if ($line =~ /^(\s*)(?:my \$grammar|\$grammar) = .*->build_grammar\(\s*$/) {
        my $indent = $1;

        # Check if next line is a rule (starts with [ followed by quoted string)
        if ($i + 1 < @lines && $lines[$i + 1] =~ /^(\s*)\[\s*'/) {
            # Insert rules => [ after the build_grammar(
            splice @lines, $i + 1, 0, "${indent}    rules => [\n";
            $modified = 1;

            # Find the closing paren and add closing bracket for rules
            for (my $j = $i + 2; $j < @lines; $j++) {
                if ($lines[$j] =~ /^(\s*)\)\s*;\s*$/) {
                    $lines[$j] = "$1    ]\n$1);\n";
                    last;
                }
            }
        }
        next;
    }
}

# Write the modified content back
if ($modified) {
    open my $out, '>', $file or die "Cannot write $file: $!\n";
    print $out @lines;
    close $out;
    say "Modified $file";
} else {
    say "No changes needed for $file";
}

