    # A -> B A x, B -> C, C -> epsilon, A -> z (hidden recursion)
    $result = $parser->parse_string('zx');
    ok $result, 'Parse zx (hidden recursion through nullable B)';

    # A -> B A x, B -> C, C -> A y, A -> z (indirect recursion)
    $result = $parser->parse_string('zyx');
    ok $result, 'Parse zyx (indirect recursion through B and C)';

    # Complex combination
    $result = $parser->parse_string('zxyx');
    ok $result, 'Parse zxyx (combined hidden and indirect)';
};

