    82→class SPPFViterbiElement :isa(Element) {
    83→    field $score     :param :reader;
    84→    field $path      :param :reader;
    85→    field $sppf_node :param :reader;
    86→    field $forest    :param :reader;
    87→
    88→    method multiply( $other, $swap = undef ) {
    89→
    90→        # Create new combined SPPF node representing sequence
    91→        my $combined_node =
    92→          $forest->create_sequence_node( $sppf_node, $other->sppf_node );
    93→
    94→        return SPPFViterbiElement->new(
    95→            score     => $score + $other->score,
    96→            path      => [ $path->@*, $other->path->@* ],
    97→            sppf_node => $combined_node,
    98→            forest    => $forest
    99→        );
   100→    }
   101→
   102→    method add( $other, $swap = undef ) {
   103→
   104→        # Add alternative to SPPF while keeping best score
   105→        $forest->add_alternative( $sppf_node, $other->sppf_node );
   106→
   107→        # Return the better scoring element (classic Viterbi behavior)
   108→        return $self if $score > $other->score;
   109→        return $other;
   110→    }
   111→
   112→    method equals( $other, $swap = undef ) {
   113→        return 0 unless ref($other) eq ref($self);
   114→        return $score == $other->score
   115→          && join( ',', $path->@* ) eq join( ',', $other->path->@* );
   116→    }
