   118→    method to_string(@) {
   119→        return sprintf( '%.4f[%s] SPPF:%s',
   120→            exp($score), join( ',', $path->@* ), $sppf_node );
   121→    }
   122→
   123→    method probability() { exp($score) }
   124→    method best_path()   { $path->[0] }
