   254→class EarleyChart {
   255→    field $semiring :param;
   256→    field %chart;
   257→    field @by_end_pos;
   258→    field %predicted;    # Track what we've predicted at each position
   259→    field %completed;    # Track what we've completed
   260→
   261→    method add_item($earley_item) {
   262→        $chart{ $earley_item->key } = $earley_item;
   263→    }
   264→
   265→    method get_element($key) { $chart{$key} }
   266→
   267→    method add_element( $item, $element ) {
   268→        my $key     = $item->key;
   269→        my $current = $self->get_element($key);
   270→        $chart{$key} = $current ? $current + $element : $element;
   271→
   272→        push( $by_end_pos[ $item->end_pos ]->@*, $item );
   273→
   274→        return $chart{$key};
   275→    }
   276→
   277→    method items_ending_at($end_pos) {
   278→        return $by_end_pos[$end_pos]->@* if $by_end_pos[$end_pos];
   279→        return;
   280→    }
   281→
   282→    method has_item($item) {
   283→        return exists( $chart{$item} );
   284→    }
   285→
   286→    method has_predicted( $nonterminal, $pos, $rule_id ) {
   287→        return exists( $predicted{"$nonterminal|$pos|$rule_id"} );
   288→    }
   289→
   290→    method mark_predicted( $nonterminal, $pos, $rule_id ) {
   291→        $predicted{"$nonterminal|$pos|$rule_id"} = 1;
   292→    }
   293→
   294→    method has_completed($item) {
   295→        return exists( $completed{$item} );
   296→    }
   297→
   298→    method mark_completed($item) {
   299→        $completed{$item} = 1;
   300→    }
   301→
   302→    method goal_value( $start_symbol, $n ) {
   303→
   304→        # Find all complete items that span [0,n] with LHS = start_symbol
   305→        my $result = $semiring->add_id;
   306→
   307→        my @items = $self->items_ending_at($n);
   308→
   309→        for my $item (@items) {
   310→            next unless $item->complete;
   311→            next unless $item->start_pos == 0;
   312→            next unless $item->rule->lhs eq $start_symbol;
   313→
   314→            my $element = $self->get_element($item);
   315→            if ($element) {
   316→                $result = $result + $element;
   317→            }
   318→        }
   319→
   320→        # Check if we found any valid parses
   321→        return $result == $semiring->add_id ? undef : $result;
   322→    }
   323→}
