use 5.42.0;
use Test2::V0;
use FindBin      qw($RealBin);
use experimental qw(defer);
defer { done_testing() }

require "$RealBin/../chalk";

# Simple arithmetic
my $grammar = Grammar->build_grammar(
    rules => [
        [ 'E' => ['num'] ],
    ]
);

my $parser = Parser->new(grammar => $grammar);

my $result = $parser->parse_string('num');
