    rules => [
        [ 'E' => [qw(E + E)] ],
        [ 'E' => ['num'] ],
    ]
);

$parser = Parser->new(grammar => $grammar);
$result = $parser->parse_string('num+num');
say "Addition result: " . (defined $result ? ref($result) . " - $result" : "undef");

