        if ( ref($first) eq 'ARRAY' && @$first >= 2 && ref($first->[1]) eq 'ARRAY' ) {
            # First arg is a rule, not auto_insert
            $auto_insert = [];
            @rules = ($first, @args);
        } else {
            # First arg is auto_insert
