    my %rules_hash = ();
    for my $r (@rules) {
        my ( $lhs, $rhs ) = @$r;
        if ( @$auto_insert && @$rhs > 1 ) {
            $r->[1] = insert( $auto_insert, @$rhs );
        }
        push( @{ $rules_hash{$lhs} //= [] }, new_rule(@$r) );
    }
    return Grammar->new( rules => \%rules_hash, start_symbol => $rules[0]->[0] );
}

