#!/usr/bin/env perl
# ABOUTME: Convert build_grammar calls from positional to named parameters
# ABOUTME: Wraps rule arrays in rules => [...] format

use 5.42.0;
use strict;
use warnings;

my $file = $ARGV[0] or die "Usage: $0 <test_file>\n";

# Read file
open my $fh, '<', $file or die "Cannot open $file: $!\n";
my $content = do { local $/; <$fh> };
close $fh;

my $modified = 0;

# Pattern: Chalk::Grammar->build_grammar( followed by [ on the next line or same line
# We need to add "rules => [" wrapper and close it before the closing )

# Find all build_grammar calls that don't already have rules =>
while ($content =~ /Chalk::Grammar->build_grammar\(\s*\n?\s*(\[)/g) {
    my $pos = pos($content) - 1;  # Position of the [

    # Check if this is already wrapped with rules =>
    my $before = substr($content, 0, $pos);
    if ($before =~ /rules\s*=>\s*$/) {
        next;  # Already has rules =>
    }

    # Find the matching closing parenthesis for build_grammar
    my $depth = 1;
    my $paren_depth = 1;
    my $i = $pos;
    my $start = $pos;

    while ($i < length($content) && $depth > 0) {
        my $char = substr($content, $i, 1);
        if ($char eq '[') {
            $depth++;
        } elsif ($char eq ']') {
            $depth--;
        } elsif ($char eq '(') {
            $paren_depth++;
        } elsif ($char eq ')') {
            $paren_depth--;
            if ($paren_depth == 0) {
                # Found the closing ) for build_grammar
                my $end = $i;

                # Extract the rules section
                my $rules_section = substr($content, $start, $end - $start);

                # Wrap it
                my $new_section = "\n        rules => [\n        $rules_section\n        ]";

                # Replace in content
                substr($content, $start, $end - $start, $new_section);
                $modified = 1;

                # Adjust position for next search
                pos($content) = $start + length($new_section);
                last;
            }
        }
        $i++;
    }
}

if ($modified) {
    open my $out, '>', $file or die "Cannot write $file: $!\n";
    print $out $content;
    close $out;
    say "Converted $file to named parameters";
} else {
    say "No changes needed for $file";
}

