    [ 'S' => ['E'] ],           # Augmented start rule
    [ 'E' => [qw(E + T)] ],
    [ 'E' => ['T'] ],
    [ 'T' => [qw(T * F)] ],
    [ 'T' => ['F'] ],
    [ 'F' => [qw/( E )/] ],
    [ 'F' => ['num'] ],
);

say "Start rule: " . $grammar->start_rule;

