#!/usr/bin/env perl
# ABOUTME: Convert build_grammar() calls to use rules => [] format
# ABOUTME: One-time migration script for converting positional to named params
use 5.42.0;
use strict;
use warnings;

my $file = shift or die "Usage: $0 <file>\n";

# Read the file
open my $fh, '<', $file or die "Can't open $file: $!\n";
my @lines = <$fh>;
close $fh;

# Track state
my $in_grammar = 0;
my $grammar_indent = '';
my @output;

for (my $i = 0; $i < @lines; $i++) {
    my $line = $lines[$i];

    # Check if this is a build_grammar call
    if ($line =~ /^(\s*)my\s+\$\w+\s*=\s*Chalk::Grammar->build_grammar\(\s*$/) {
        $grammar_indent = $1;
        # Check next line to see if it's already converted
        if ($i + 1 < @lines && $lines[$i + 1] =~ /^\s*rules\s*=>/) {
            # Already converted, just pass through
            push @output, $line;
        } else {
            # Need to convert - add rules => [
            push @output, $line;
            push @output, $grammar_indent . "    rules => [\n";
            $in_grammar = 1;
        }
    }
    elsif ($in_grammar && $line =~ /^$grammar_indent\);/) {
        # End of grammar - close the rules array
        push @output, $grammar_indent . "    ]\n";
        push @output, $line;
        $in_grammar = 0;
    }
    elsif (!$in_grammar) {
        push @output, $line;
    }
    else {
        # Inside grammar - indent the rule lines
        if ($line =~ /^$grammar_indent(\s+)/) {
            # Add extra indentation
            $line =~ s/^$grammar_indent/$grammar_indent    /;
        }
        push @output, $line;
    }
}

# Write the file back
open $fh, '>', $file or die "Can't write $file: $!\n";
print $fh @output;
close $fh;

say "Converted $file";

