subtest 'Basic SPPFViterbi functionality' => sub {
    my $grammar = Chalk::Grammar->build_grammar(
        rules => [
            [ 'E' => [qw(E + E)] ],
            [ 'E' => [qw(E * E)] ],
            [ 'E' => ['n'] ],
        ]
    );

    my $parser = Chalk::Parser->new(
        grammar => $grammar,
        semiring => SPPFViterbiSemiring->new()
    );

    my $result = $parser->parse_string('n+n*n');
